script:
printf '[s]\nhost=h\nport=8\n' > /tmp/c.ini
declare -A s
section=""
while IFS= read -r line; do
  case "$line" in
    \[*\])
      section=${line#[}
      section=${section%]}
      ;;
    *=*)
      k=${line%%=*}
      v=${line#*=}
      [[ "$section" == "s" ]] && s[$k]=$v
      ;;
  esac
done < /tmp/c.ini
echo "${s[host]}:${s[port]}"
